/**
 * @file Matches option texts against a typed query.
 *
 * match strips diacritics before matching, so "cafe" matches "Café". Case is ignored the same way, until `caseSensitive` says otherwise.
 */
import { match } from './match.js'

/**
 * getMatchedIndexes
 * Finds which options a query matches, best first. Each option has one text per key it matches by.
 *
 * @param {object} opts
 * @param {string[][]} opts.texts Each option's texts
 * @param {string} opts.query Typed query
 * @param {boolean} [opts.caseSensitive] Take case into account
 * @returns {number[]} Word-start matches on any text first, then inside-word matches.
 */
export function getMatchedIndexes({ texts, query, caseSensitive }) {
  const wordStartIndexes = getMatchingIndexes({
    texts,
    query,
    insideWords: false,
    caseSensitive,
  })
  const insideWordIndexes = getMatchingIndexes({
    texts,
    query,
    insideWords: true,
    caseSensitive,
  })
  return Array.from(new Set([...wordStartIndexes, ...insideWordIndexes]))
}

/**
 * hasPerfectMatch
 * Checks whether the query equals one of the texts, ignoring diacritics.
 *
 * @param {object} opts
 * @param {string[]} opts.texts Texts to search
 * @param {string} opts.query Typed query
 * @param {boolean} [opts.caseSensitive] Take case into account
 * @returns {boolean}
 */
export function hasPerfectMatch({ texts, query, caseSensitive }) {
  return texts.some(text => isPerfectMatch({ text, query, caseSensitive }))
}

/**
 * getMatchingIndexes
 * Gets the indexes of the options where any text matches the query.
 *
 * @param {object} opts
 * @param {string[][]} opts.texts Each option's texts
 * @param {string} opts.query Typed query
 * @param {boolean} opts.insideWords Match inside words too
 * @param {boolean} [opts.caseSensitive] Take case into account
 * @returns {number[]}
 */
function getMatchingIndexes({ texts, query, insideWords, caseSensitive }) {
  return texts.flatMap((optionTexts, index) => {
    const isMatch = optionTexts.some(
      text => match({ text, query, insideWords, caseSensitive }).length,
    )
    return isMatch ? [index] : []
  })
}

/**
 * isPerfectMatch
 * Checks whether the query covers the whole text.
 *
 * @param {object} opts
 * @param {string} opts.text Text to compare
 * @param {string} opts.query Typed query
 * @param {boolean} [opts.caseSensitive] Take case into account
 */
function isPerfectMatch({ text, query, caseSensitive }) {
  if (text.length !== query.length) return false

  const ranges = match({ text, query, insideWords: true, caseSensitive })
  if (!ranges.length) return false
  return ranges[0][0] === 0 && ranges[ranges.length - 1][1] === text.length
}
